(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 980, H = 300;
  draw.viewbox(0, 0, W, H);

  var SERIF = 'Georgia, "Times New Roman", serif';
  var INK = '#000';
  var HILITE = '#8ec5f0';

  var S = { t: 0.32, mode: 'compare', showAlt: true, showFormula: false };
  var lastStats = null;

  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }

  /* ---------- text helper ---------- */
  function labelTxt(g, str, x, y, opts) {
    opts = opts || {};
    var t = g.text(str);
    t.font({
      family: SERIF,
      size: opts.size || 17,
      style: opts.style || 'italic',
      anchor: opts.anchor || 'middle',
      leading: 1
    });
    t.fill(opts.fill || INK);
    t.attr({ x: x, y: y, 'text-anchor': opts.anchor || 'middle', 'dominant-baseline': 'middle' });
    var ts = t.node.getElementsByTagName('tspan');
    for (var i = 0; i < ts.length; i++) { ts[i].setAttribute('x', x); ts[i].setAttribute('dy', 0); }
