// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 980, H = 300;
  draw.viewbox(0, 0, W, H);

  var SERIF = 'Georgia, "Times New Roman", serif';
  var INK = '#000';
  var HILITE = '#8ec5f0';

  var S = { t: 0.32, mode: 'compare', showAlt: true, showFormula: false };
  var lastStats = null;

  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }

  /* ---------- text helper ---------- */
  function labelTxt(g, str, x, y, opts) {
    opts = opts || {};
    var t = g.text(str);
    t.font({
      family: SERIF,
      size: opts.size || 17,
      style: opts.style || 'italic',
      anchor: opts.anchor || 'middle',
      leading: 1
    });
    t.fill(opts.fill || INK);
    t.attr({ x: x, y: y, 'text-anchor': opts.anchor || 'middle', 'dominant-baseline': 'middle' });
    var ts = t.node.getElementsByTagName('tspan');
    for (var i = 0; i < ts.length; i++) { ts[i].setAttribute('x', x); ts[i].setAttribute('dy', 0); }
    if (opts.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function interactive(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }

  function arcPath(g, cx, cy, r, a0, a1, width) {
    var pts = [], n = 48;
    for (var i = 0; i <= n; i++) {
      var a = a0 + (a1 - a0) * i / n;
      pts.push([cx + r * Math.cos(a), cy - r * Math.sin(a)]);
    }
    return g.polyline(pts).fill('none').stroke({ color: INK, width: width || 1.2, linecap: 'round' });
  }

  /* ---------- drag support ---------- */
  var dragState = null;
  function toUser(evt) {
    var pt = draw.node.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    return pt.matrixTransform(draw.node.getScreenCTM().inverse());
  }
  window.addEventListener('pointermove', function (e) {
    if (!dragState) return;
    var p = toUser(e);
    var nt = (p.x - dragState.ax) / dragState.baseW;
    setSliderValue(clamp(nt, -0.45, 0.95));
  });
  window.addEventListener('pointerup', function () { dragState = null; });

  /* ---------- one triangle panel ---------- */
  function drawPanel(cfg) {
    var g = draw.group();
    var by = cfg.by, ax = cfg.ax, bw = cfg.baseW;
    var A = { x: ax, y: by };
    var G = { x: ax + bw, y: by };
    var B = { x: ax + cfg.t * bw, y: cfg.apexY };
    var F = { x: B.x, y: by };
    var obtuse = cfg.t < 0;
    var thin = { color: INK, width: 1.6, linecap: 'round', linejoin: 'round' };
    var dash = { color: INK, width: 1.4, dasharray: '6,4', linecap: 'butt' };

    /* highlighted right triangle */
    if (cfg.showAlt) {
      var hl = g.polygon([[A.x, A.y], [F.x, F.y], [B.x, B.y]])
        .fill({ color: HILITE, opacity: 0.26 }).stroke('none');
      interactive(hl, 'Right triangle: hypotenuse c, leg h, angle ' + (obtuse ? 'α′' : 'α') + ' at the base',
        'The hidden right triangle',
        'The altitude splits off a right triangle whose hypotenuse is c and whose vertical leg is h. Right-triangle trigonometry then gives h = c·sin' + (obtuse ? ' α′' : ' α') + ', which is exactly what makes the oblique triangle measurable.');
    }

    /* dashed base extension (obtuse case) */
    if (cfg.showAlt && obtuse) {
      var ext = g.line(F.x - 12, by, A.x, by).stroke(dash);
      interactive(ext, 'Dashed extension of the base b — it carries the base out to meet the altitude',
        'Extending the base',
        'When α is obtuse the perpendicular from β lands outside the triangle. The base is simply extended (dashed) to the left so the foot of the altitude has somewhere to land. The construction never fails.');
    }

    /* dashed altitude */
    if (cfg.showAlt) {
      var alt = g.line(B.x, B.y, F.x, F.y).stroke(dash);
      interactive(alt, 'Altitude h ⟂ base', 'The altitude h',
        'h is the perpendicular distance from vertex β to the base line. In the right triangle with hypotenuse c it is the side opposite the base angle, so h = c·sin α.');
      /* right-angle marker */
      g.polyline([[F.x, F.y - 10], [F.x + 10, F.y - 10], [F.x + 10, F.y]])
        .fill('none').stroke({ color: INK, width: 1.3 });
    }

    /* solid sides */
    var baseLine = g.line(A.x, A.y, G.x, G.y).stroke(thin);
    var hit = g.line(A.x, A.y, G.x, G.y).stroke({ color: '#fff', width: 16, opacity: 0 });
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip('Base b — click to ' + (S.showAlt ? 'hide' : 'drop') + ' the altitude h', e); });
    hit.on('mouseleave', hideTooltip);
    hit.on('click', function () {
      S.showAlt = !S.showAlt;
      render();
      if (S.showAlt) {
        showPopup('Dropping the altitude',
          'From β a perpendicular falls to the base line, meeting it at a right angle. This single construction converts the oblique triangle into a right triangle with hypotenuse c and height h, so h = c·sin α and Area = ½·b·h = ½·b·c·sin α.');
      }
    });

    var cSide = g.line(A.x, A.y, B.x, B.y).stroke(thin);
    var aSide = g.line(B.x, B.y, G.x, G.y).stroke(thin);
    interactive(cSide, 'Side c (from α to β) — hypotenuse of the right triangle', 'Side c',
      'c joins vertex α to vertex β. Once the altitude is drawn, c is the hypotenuse of a right triangle whose vertical leg is h, hence h = c·sin α.');
    interactive(aSide, 'Side a (from β to γ)', 'Side a', 'a is the side opposite vertex α. It plays no part in the altitude construction, but it does take part in the Law of Sines that the same altitude proves.');

    /* angle arcs at α */
    var angA = Math.atan2(A.y - B.y, B.x - A.x); /* math-convention angle of α→β */
    var arcMain = arcPath(g, A.x, A.y, 30, 0, angA);
    interactive(arcMain, 'Interior angle α = ' + (angA * 180 / Math.PI).toFixed(1) + '°', 'Angle α',
      'This is the interior angle of the triangle at vertex α, measured between the base b and the side c.');
    if (obtuse) {
      var arcSup = arcPath(g, A.x, A.y, 20, Math.PI, angA);
      interactive(arcSup, "α′ = 180° − α = " + (180 - angA * 180 / Math.PI).toFixed(1) + "°  (sin α′ = sin α)",
        "The supplement α′",
        "α′ is the angle between side c and the dashed extension of the base. The right triangle sits on α′, so h = c·sin α′. Because sin(180° − α) = sin α, this equals c·sin α: the acute formula survives unchanged.");
      var la = (Math.PI + angA) / 2;
      labelTxt(g, '\u03B1\u2032', A.x + 34 * Math.cos(la), A.y - 34 * Math.sin(la), { size: 16 });
      labelTxt(g, '\u03B1', A.x + 44 * Math.cos(angA / 2), A.y - 44 * Math.sin(angA / 2), { size: 16 });
    }

    /* vertex letters */
    labelTxt(g, '\u03B2', B.x, B.y - 19, { size: 18 });
    labelTxt(g, '\u03B3', G.x + 18, G.y - 4, { size: 18 });
    if (!obtuse) labelTxt(g, '\u03B1', A.x - 18, A.y - 4, { size: 18 });

    /* side labels */
    labelTxt(g, 'b', (A.x + G.x) / 2, by + 26, { size: 17 });
    var cm = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
    labelTxt(g, 'c', cm.x + (obtuse ? 28 : -20), cm.y + (obtuse ? 6 : 0), { size: 17 });
    var am = { x: (B.x + G.x) / 2, y: (B.y + G.y) / 2 };
    labelTxt(g, 'a', am.x - 4, am.y - 15, { size: 17 });
    if (cfg.showAlt) {
      labelTxt(g, 'h', F.x + (obtuse ? -17 : 15), (B.y + by) / 2, { size: 17 });
    }

    /* optional formula callout */
    if (cfg.showFormula && cfg.showAlt) {
      var f = obtuse
        ? 'h = c sin \u03B1\u2032 = c sin \u03B1   (\u03B1\u2032 = 180\u00B0 \u2212 \u03B1)'
        : 'h = c sin \u03B1';
      labelTxt(g, f, (A.x + G.x) / 2, by + 54, { size: 14, fill: '#14507f' });
    }

    /* drag handle on β */
    var handle = g.circle(22).center(B.x, B.y).fill({ color: '#fff', opacity: 0.001 }).stroke('none');
    handle.css('cursor', 'ew-resize');
    handle.on('mousemove', function (e) { showTooltip('Drag vertex β left or right', e); });
    handle.on('mouseleave', hideTooltip);
    handle.on('pointerdown', function (e) {
      e.preventDefault();
      dragState = { ax: ax, baseW: bw };
    });

    return { t: cfg.t, hRatio: (by - cfg.apexY) / bw, obtuse: obtuse };
  }

  /* ---------- render ---------- */
  function render() {
    draw.clear();
    var stats = [];
    if (S.mode === 'compare') {
      stats.push(drawPanel({ ax: 80, baseW: 340, by: 232, apexY: 48, t: clamp(S.t, 0.05, 0.95), showAlt: S.showAlt, showFormula: S.showFormula }));
      stats.push(drawPanel({ ax: 600, baseW: 330, by: 232, apexY: 38, t: clamp(S.t, -0.35, -0.06), showAlt: S.showAlt, showFormula: S.showFormula }));
    } else {
      stats.push(drawPanel({ ax: 290, baseW: 540, by: 235, apexY: 45, t: S.t, showAlt: S.showAlt, showFormula: S.showFormula }));
    }
    lastStats = stats;
    updateReadout();
  }

  function panelStats(t, hRatio) {
    var h = 10 * hRatio;
    var dx = 10 * t;
    var c = Math.sqrt(dx * dx + h * h);
    var aDeg = Math.atan2(h, dx) * 180 / Math.PI;
    return { h: h, c: c, a: aDeg, s: Math.sin(aDeg * Math.PI / 180) };
  }

  function line(st) {
    var o = '';
    o += '\u03B1 = ' + st.a.toFixed(1) + '\u00B0';
    if (st.a > 90) o += ' &nbsp;\u03B1\u2032 = ' + (180 - st.a).toFixed(1) + '\u00B0';
    o += '<br>c = ' + st.c.toFixed(2) + ' &nbsp; sin \u03B1 = ' + st.s.toFixed(3);
    o += '<br>h = c\u00B7sin \u03B1 = ' + st.h.toFixed(2);
    o += '<br>Area = \u00BD\u00B7b\u00B7h = ' + (0.5 * 10 * st.h).toFixed(2);
    return o;
  }

  function updateReadout() {
    var el = document.getElementById('readout');
    if (!el || !lastStats) return;
    var out = '<b>with b = 10</b><br>';
    if (lastStats.length === 2) {
      out += '<u>acute panel</u><br>' + line(panelStats(lastStats[0].t, lastStats[0].hRatio));
      out += '<br><u>obtuse panel</u><br>' + line(panelStats(lastStats[1].t, lastStats[1].hRatio));
    } else {
      out += line(panelStats(lastStats[0].t, lastStats[0].hRatio));
    }
    el.innerHTML = out;
  }

  /* ---------- controls ---------- */
  function setSliderValue(v) {
    var inp = document.getElementById('apexPositionInput');
    inp.value = v.toFixed(2);
    document.getElementById('apexPositionVal').value = inp.value;
    window.update_apexPosition(+inp.value);
  }

  window.update_apexPosition = function (v) {
    S.t = v;
    if (S.mode !== 'compare') {
      S.mode = (v < 0) ? 'obtuse' : 'acute';
      document.getElementById('caseViewInput').value = S.mode;
    }
    render();
  };

  window.toggle_caseView = function (v) {
    S.mode = v;
    if (v === 'acute' && S.t < 0.02) { setSliderValue(0.32); return; }
    if (v === 'obtuse' && S.t > -0.05) { setSliderValue(-0.3); return; }
    render();
  };

  window.toggle_showFormula = function (on) { S.showFormula = on; render(); };

  window.trigger_buildAltitude = function () {
    S.showAlt = !S.showAlt;
    render();
    if (S.showAlt) {
      showPopup('Dropping the altitude',
        'A perpendicular from β meets the base line at a right angle. That single stroke creates a right triangle with hypotenuse c and vertical leg h, so h = c·sin α — and when α is obtuse the same stroke lands on the dashed extension, using α′ = 180° − α with sin α′ = sin α.');
    }
  };

  /* ---------- demo steps ---------- */
  var steps = [
    {
      title: 'The figure',
      narr: 'Two oblique triangles sharing the same base b. On the left the angle at α is acute and the altitude h lands inside the base; on the right α is obtuse and h lands on a dashed extension of the base.',
      state: { mode: 'compare', t: 0.32, alt: true, form: false }
    },
    {
      title: 'An oblique triangle',
      narr: 'A triangle with sides a, b, c and no right angle of its own. Vertex β sits above the base b, between α and γ. Nothing here lets us read off a height directly.',
      state: { mode: 'acute', t: 0.32, alt: false, form: false }
    },
    {
      title: 'Drop the altitude',
      narr: 'Click the base: a dashed perpendicular h falls from β to a point inside b, with a right-angle marker at its foot. The left piece is now a right triangle with hypotenuse c and leg h, so h = c·sin α.',
      state: { mode: 'acute', t: 0.32, alt: true, form: true }
    },
    {
      title: 'Slide β toward α',
      narr: 'As β moves left, the foot of the altitude slides toward α and the angle at α opens wider. Watch the foot approach the left end of the base.',
      state: { mode: 'acute', t: 0.05, alt: true, form: true }
    },
    {
      title: 'The foot leaves the base',
      narr: 'Push β past α and the angle at α becomes obtuse. The perpendicular now lands outside the triangle, so the base must be carried leftward by a dashed extension to catch it.',
      state: { mode: 'obtuse', t: -0.3, alt: true, form: false }
    },
    {
      title: 'Which angle gives the height?',
      narr: 'Two arcs appear at the lower left: the interior angle α and, beside it on the extension, α′ = 180° − α. The right triangle is built on α′, so h = c·sin α′ — and since sin α′ = sin α, the same formula survives.',
      state: { mode: 'obtuse', t: -0.3, alt: true, form: true }
    },
    {
      title: 'Both cases together',
      narr: 'Side by side, the two constructions are identical in spirit: one altitude, one right triangle, one height h = c·sin α feeding Area = ½·b·h = ½·b·c·sin α.',
      state: { mode: 'compare', t: -0.25, alt: true, form: true }
    }
  ];
  var stepIndex = 0;

  window.goStep = function (i) {
    stepIndex = clamp(i, 0, steps.length - 1);
    var st = steps[stepIndex].state;
    S.t = st.t; S.mode = st.mode; S.showAlt = st.alt; S.showFormula = st.form;
    var slider = document.getElementById('apexPositionInput');
    slider.value = st.t.toFixed(2);
    document.getElementById('apexPositionVal').value = slider.value;
    document.getElementById('caseViewInput').value = st.mode;
    document.getElementById('showFormulaInput').checked = st.form;
    document.getElementById('demoNarration').innerHTML =
      '<b>' + steps[stepIndex].title + '</b><br>' + steps[stepIndex].narr;
    document.getElementById('stepLabel').textContent =
      'Step ' + (stepIndex + 1) + ' / ' + steps.length;
    render();
  };
  window.nextStep = function () { goStep(stepIndex + 1); };
  window.prevStep = function () { goStep(stepIndex - 1); };

  goStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

