(function () {
  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');

  var SERIF = 'Georgia, "Times New Roman", serif';
  var INK = '#000';
  var HILITE = '#bcdcf5';

  var S = { t: 0.32, mode: 'compare', showAlt: true, showHL: false, showFormula: false };
  var cw = container.clientWidth || 900, ch = container.clientHeight || 600;
  var lastStats = [];

  function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }

  /* ---------- text with white halo ---------- */
  function labelTxt(g, str, x, y, size, fill, anchor) {
    var t = g.text(str);
    t.font({ family: SERIF, size: size, style: 'italic', anchor: anchor || 'middle', leading: 1 });
    t.fill(fill || INK);
    t.attr({
      x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'middle',
      'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(2, size * 0.25),
      'stroke-linejoin': 'round'
