    var obtuse = t < 0;
    var padL = obtuse ? 0.30 * pw : 0.13 * pw;
    var padR = 0.10 * pw;
    var bw = pw - padL - padR;
    var ax = padL;
    var baseY = 0.74 * ph, apexY = 0.12 * ph;

    var A = { x: ax, y: baseY }, G = { x: ax + bw, y: baseY };
    var B = { x: ax + t * bw, y: apexY };
    var F = { x: B.x, y: baseY };

    var FS = Math.max(12, pw * 0.058);
    var SW = Math.max(1, pw * 0.0050);
