        .fill({ color: HILITE, opacity: 0.45 }).stroke('none');
      interactive(hl, 'Right triangle: hypotenuse c, leg h, base angle ' + (obtuse ? 'α′' : 'α'),
        'The hidden right triangle',
        'The altitude splits off a right triangle whose hypotenuse is c and whose vertical leg is h. Right-triangle trigonometry then gives h = c·sin' + (obtuse ? ' α′' : ' α') + ', which is what makes the oblique triangle measurable.');
    }

    /* dashed base extension (obtuse only) */
    if (S.showAlt && obtuse) {
      var ext = g.line(F.x - 0.035 * pw, baseY, A.x, baseY).stroke(dash);
      interactive(ext, 'Dashed extension of the base b', 'Extending the base',
        'When α is obtuse the perpendicular from β lands outside the triangle, so the base line is simply extended to the left to meet it. The construction never fails.');
    }

    /* dashed altitude + right-angle square */
    if (S.showAlt) {
      var alt = g.line(B.x, B.y, F.x, F.y).stroke(dash);
      interactive(alt, 'Altitude h ⟂ base line', 'The altitude h',
        'h is the perpendicular distance from vertex β to the base line. In the right triangle with hypotenuse c it is the side opposite the base angle, so h = c·sin α.');
      g.polyline([[F.x, F.y - mk], [F.x + mk, F.y - mk], [F.x + mk, F.y]])
