      if (S.showAlt) S.showHL = true;
      syncInputs(); render();
      if (S.showAlt) showPopup('Dropping the altitude',
        'From β a perpendicular falls to the base line, meeting it at a right angle. That one stroke turns the oblique triangle into a right triangle with hypotenuse c and leg h, so h = c·sin α and Area = ½·b·h = ½·b·c·sin α.');
    });

    var cSide = g.line(A.x, A.y, B.x, B.y).stroke(solid);
    var aSide = g.line(B.x, B.y, G.x, G.y).stroke(solid);
    interactive(cSide, 'Side c (α → β) — hypotenuse of the right triangle', 'Side c',
      'c joins vertex α to vertex β. Once the altitude is drawn, c is the hypotenuse of a right triangle whose vertical leg is h, hence h = c·sin α.');
    interactive(aSide, 'Side a (β → γ)', 'Side a',
      'a is the side opposite vertex α. It takes no part in this altitude construction, but it does appear in the Law of Sines that the same altitude proves.');

    /* angle arcs at α */
    var angA = Math.atan2(A.y - B.y, B.x - A.x);
    var rA = (obtuse ? 0.17 : 0.15) * bw;
    var arcMain = arcPath(g, A.x, A.y, rA, 0, angA, SW * 0.8);
    interactive(arcMain, 'Interior angle α = ' + (angA * 180 / Math.PI).toFixed(1) + '°', 'Angle α',
      'The interior angle of the triangle at vertex α, measured between the base b and the side c.');

    if (obtuse) {
      var r2 = 0.10 * bw;
      var arcSup = arcPath(g, A.x, A.y, r2, Math.PI, angA, SW * 0.8);
      interactive(arcSup, "α′ = 180° − α = " + (180 - angA * 180 / Math.PI).toFixed(1) + '°   (sin α′ = sin α)',
        'The supplement α′',
        'α′ lies between side c and the dashed extension of the base. The right triangle sits on α′, so h = c·sin α′. Because sin(180° − α) = sin α, this equals c·sin α: the acute formula survives unchanged.');
      var la = (Math.PI + angA) / 2;
      labelTxt(g, '\u03B1\u2032', A.x + (r2 + 0.075 * pw) * Math.cos(la), A.y - (r2 + 0.075 * pw) * Math.sin(la), FS * 0.95);
      labelTxt(g, '\u03B1', A.x + (rA + 0.075 * pw) * Math.cos(angA / 2), A.y - (rA + 0.075 * pw) * Math.sin(angA / 2), FS * 0.95);
    }

