    labelTxt(g, '\u03B2', B.x, B.y - FS * 0.95, FS * 1.05);
    labelTxt(g, '\u03B3', G.x + 0.055 * pw, G.y - FS * 0.25, FS * 1.05);
    if (!obtuse) labelTxt(g, '\u03B1', A.x - 0.055 * pw, A.y - FS * 0.2, FS * 1.05);

