    var cm = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
    labelTxt(g, 'c', cm.x + (obtuse ? 0.065 * pw : -0.055 * pw), cm.y, FS);
    var am = { x: (B.x + G.x) / 2, y: (B.y + G.y) / 2 };
    labelTxt(g, 'a', am.x, am.y - FS * 0.95, FS);
