        stats.push(drawPanel(325, 0, 305, 205, tb));
      } else {
        draw.viewbox(0, 0, 350, 425);
        stats.push(drawPanel(0, 0, 350, 205, ta));
        stats.push(drawPanel(0, 215, 350, 205, tb));
      }
    } else {
      draw.viewbox(0, 0, 370, 225);
      stats.push(drawPanel(0, 0, 370, 225, S.t));
