      out += '<u>acute</u><br>' + lineFor(panelStats(lastStats[0].t, lastStats[0].hRatio));
      out += '<br><u>obtuse</u><br>' + lineFor(panelStats(lastStats[1].t, lastStats[1].hRatio));
