    {
      title: 'Drop the altitude',
      narr: 'A dashed perpendicular h falls from β to a point inside b, with a right-angle marker at its foot. The shaded piece is a right triangle with hypotenuse c and leg h, so h = c·sin α.',
      st: { mode: 'acute', t: 0.32, alt: true, hl: true, form: true }
    },
    {
      title: 'Slide β toward α',
      narr: 'As β moves left, the foot of the altitude slides toward α and the angle at α opens wider. Watch the foot approach the left end of the base.',
      st: { mode: 'acute', t: 0.06, alt: true, hl: true, form: true }
    },
    {
      title: 'The foot leaves the base',
      narr: 'Push β past α and the angle at α becomes obtuse. The perpendicular now lands outside the triangle, so the base is carried leftward by a dashed extension to catch it.',
      st: { mode: 'obtuse', t: -0.30, alt: true, hl: true, form: false }
    },
    {
      title: 'Which angle gives the height?',
      narr: 'Two arcs sit at the lower left: the interior angle α, and α′ = 180° − α on the extension. The right triangle is built on α′, so h = c·sin α′ — and since sin α′ = sin α, the same formula survives.',
      st: { mode: 'obtuse', t: -0.30, alt: true, hl: true, form: true }
    },
    {
      title: 'Both cases together',
      narr: 'Side by side the constructions are identical in spirit: one altitude, one right triangle, one height h = c·sin α feeding Area = ½·b·h = ½·b·c·sin α.',
      st: { mode: 'compare', t: -0.28, alt: true, hl: true, form: true }
    }
  ];
  var stepIndex = 0;

  window.goStep = function (i) {
    stepIndex = clamp(i, 0, steps.length - 1);
    var s = steps[stepIndex].st;
    S.t = s.t; S.mode = s.mode; S.showAlt = s.alt; S.showHL = s.hl; S.showFormula = s.form;
    var sl = document.getElementById('apexPositionInput');
    sl.value = s.t.toFixed(2);
    document.getElementById('apexPositionVal').value = sl.value;
    syncInputs();
    document.getElementById('demoNarration').innerHTML =
      '<b>' + steps[stepIndex].title + '</b><br>' + steps[stepIndex].narr;
    document.getElementById('stepLabel').textContent = (stepIndex + 1) + ' / ' + steps.length;
    render();
  };
  window.nextStep = function () { goStep(stepIndex + 1); };
  window.prevStep = function () { goStep(stepIndex - 1); };

  document.addEventListener('fig-resize', function (e) {
    cw = e.detail.width || cw; ch = e.detail.height || ch; render();
  });

  goStep(0);
  window.__markRendered();
})();
